505	            'Mean Price': f"${s['price_mean']:.0f}" if s['price_mean'] else 'N/A',
506	            'Pro Host Share': f"{s['pro_host_share']:.1f}%",
507	            'Entire Home Share': f"{s['room_counts'].get('Entire home/apt', 0) / s['total_listings'] * 100:.1f}%",
508	            'Avg Reviews/Mo': f"{s['reviews_pm_mean']:.2f}" if s['reviews_pm_mean'] else '0.00',
509	            'Mean Availability': f"{s['avail_mean']:.0f} days",
510	            'Mean Min Nights': f"{s['min_nights_mean']:.1f}",
511	        })
512	    return rows
