514	def format_kpi_rows(rows):
515	    html = '<table><thead><tr>'
516	    for key in rows[0]:
517	        html += f'<th>{key}</th>'
518	    html += '</tr></thead><tbody>'
519	    for i, row in enumerate(rows):
520	        bg = '#f8f9fa' if i % 2 == 0 else '#ffffff'
521	        html += f'<tr style="background:{bg}">'
522	        for j, (key, val) in enumerate(row.items()):
523	            style = 'font-weight:600' if key == 'City' else ''
524	            html += f'<td style="{style}">{val}</td>'
525	        html += '</tr>'
526	    html += '</tbody></table>'
527	    return html
