def chart_review_recency(stats):
    fig, ax = plt.subplots(figsize=(10, 4.5))
    cities = CITIES_ORDER
    pcts_3m = [stats[c]['review_recent_3m_pct'] for c in cities]
    pcts_6m = [stats[c]['review_recent_6m'] / stats[c]['total_listings'] * 100 for c in cities]
    pcts_12m = [stats[c]['review_recent_12m'] / stats[c]['total_listings'] * 100 for c in cities]

    x = np.arange(len(cities))
    width = 0.25
    ax.bar(x - width, pcts_3m, width, label='Last 3 months', color='#2196F3', edgecolor='white')
    ax.bar(x, pcts_6m, width, label='Last 6 months', color='#64B5F6', edgecolor='white')
    ax.bar(x + width, pcts_12m, width, label='Last 12 months', color='#BBDEFB', edgecolor='white')

    ax.set_title('Review Recency: % of Listings with a Review Within Period', fontsize=12, fontweight='bold')
    ax.set_xticks(x)
    ax.set_xticklabels(cities, rotation=45)
    ax.set_ylabel('% of Listings')
    ax.legend(fontsize=8)
    ax.spines['top'].set_visible(False)
    ax.spines['right'].set_visible(False)
    return fig_to_b64(fig)

def chart_price_vs_availability(stats):
    fig, ax = plt.subplots(figsize=(8, 6))
    for i, city in enumerate(CITIES_ORDER):
        ax.scatter(stats[city]['price_median'], stats[city]['avail_mean'],
                   s=stats[city]['total_listings'] / 500, alpha=0.7,
                   color=CITY_COLORS[i], label=city, edgecolors='white', linewidth=0.5)
    ax.set_xlabel('Median Nightly Price (USD)')
    ax.set_ylabel('Mean Availability (Days/Year)')
    ax.set_title('Price vs. Availability by City', fontsize=14, fontweight='bold')
    ax.legend(fontsize=8, loc='best')
    ax.spines['top'].set_visible(False)
    ax.spines['right'].set_visible(False)
    return fig_to_b64(fig)

# ── KPI Table ─────────────────────────────────────────────────────────────────

def generate_kpi_table(stats):
    rows = []
    for city in CITIES_ORDER:
        s = stats[city]
        rows.append({
            'City': city,
            'Total Listings': f"{s['total_listings']:,}",
            'Median Price': f"${s['price_median']:.0f}" if s['price_median'] else 'N/A',
            'Mean Price': f"${s['price_mean']:.0f}" if s['price_mean'] else 'N/A',
            'Pro Host Share': f"{s['pro_host_share']:.1f}%",
            'Entire Home Share': f"{s['room_counts'].get('Entire home/apt', 0) / s['total_listings'] * 100:.1f}%",
            'Avg Reviews/Mo': f"{s['reviews_pm_mean']:.2f}" if s['reviews_pm_mean'] else '0.00',
            'Mean Availability': f"{s['avail_mean']:.0f} days",
            'Mean Min Nights': f"{s['min_nights_mean']:.1f}",
        })
    return rows

def format_kpi_rows(rows):
    html = '<table><thead><tr>'
    for key in rows[0]:
        html += f'<th>{key}</th>'
    html += '</tr></thead><tbody>'
    for i, row in enumerate(rows):
        bg = '#f8f9fa' if i % 2 == 0 else '#ffffff'
        html += f'<tr style="background:{bg}">'
        for j, (key, val) in enumerate(row.items()):
            style = 'font-weight:600' if key == 'City' else ''
            html += f'<td style="{style}">{val}</td>'
        html += '</tr>'
    html += '</tbody></table>'
    return html

# ── HTML Report Builder ──────────────────────────────────────────────────────

def build_report(stats, charts):
    kpi_rows = generate_kpi_table(stats)

    # Find extremes for takeaways
    max_price_city = max(CITIES_ORDER, key=lambda c: stats[c]['price_median'] or 0)
    min_price_city = min(CITIES_ORDER, key=lambda c: stats[c]['price_median'] or float('inf'))
    max_pro_city = max(CITIES_ORDER, key=lambda c: stats[c]['pro_host_share'])
    min_pro_city = min(CITIES_ORDER, key=lambda c: stats[c]['pro_host_share'])
    max_entire_city = max(CITIES_ORDER, key=lambda c: stats[c]['room_counts'].get('Entire home/apt', 0) / stats[c]['total_listings'] * 100)
    max_reviews_city = max(CITIES_ORDER, key=lambda c: stats[c]['reviews_pm_mean'] or 0)
    max_avail_city = max(CITIES_ORDER, key=lambda c: stats[c]['avail_mean'] or 0)
    max_listings_city = max(CITIES_ORDER, key=lambda c: stats[c]['total_listings'])

    # Rankings
    price_rank = sorted(CITIES_ORDER, key=lambda c: stats[c]['price_median'] or 0, reverse=True)
    pro_rank = sorted(CITIES_ORDER, key=lambda c: stats[c]['pro_host_share'], reverse=True)

    def stat(s, key, fmt='.1f'):
        val = stats[s].get(key)
        if val is None:
            return 'N/A'
        return f'{val:{fmt}}'

    # Build individual city stats paragraphs
    city_details = ''
    for city in CITIES_ORDER:
        s = stats[city]
        median_p = f"${s['price_median']:.0f}" if s['price_median'] else 'N/A'
        mean_p = f"${s['price_mean']:.0f}" if s['price_mean'] else 'N/A'
        city_details += f'''
        <tr>
            <td style="font-weight:600">{city}</td>
            <td>{s['total_listings']:,}</td>
            <td>{median_p}</td>
            <td>{mean_p}</td>
            <td>{s['room_counts'].get('Entire home/apt', 0) / s['total_listings'] * 100:.1f}%</td>
            <td>{s['pro_host_share']:.1f}%</td>
            <td>{s['reviews_pm_mean']:.2f}</td>
            <td>{s['avail_mean']:.0f}</td>
            <td>{s['min_nights_mean']:.1f}</td>
        </tr>'''

    # Room type price details
    room_price_details = ''
    for city in CITIES_ORDER:
        s = stats[city]
        for rt in ['Entire home/apt', 'Private room', 'Shared room']:
            rps = s['room_price_stats'].get(rt, {})
            if rps:
                room_price_details += f'''
                <tr>
                    <td style="font-weight:600">{city}</td>
                    <td>{rt}</td>
                    <td>{rps['count']:,}</td>
                    <td>${rps['median']:.0f}</td>
                    <td>${rps['mean']:.0f}</td>
                </tr>'''

    # Pro host share for takeaways
    pro_share_strs = []
    for city in CITIES_ORDER:
        s = stats[city]
        pro_share_strs.append(f"<li><strong>{city}:</strong> {s['pro_host_share']:.1f}% of listings from professional hosts, {s['host_listings_mean']:.1f} avg listings/host</li>")

    # Room type breakdown for overview
    room_overview_rows = ''
    for city in CITIES_ORDER:
        s = stats[city]
        room_overview_rows += f'''
        <tr>
            <td style="font-weight:600">{city}</td>
            <td>{s['total_listings']:,}</td>'''
        for rt in ROOM_TYPES:
            c = s['room_counts'].get(rt, 0)
            pct = c / s['total_listings'] * 100 if s['total_listings'] else 0
            room_overview_rows += f'<td>{c:,} ({pct:.1f}%)</td>'
        room_overview_rows += '</tr>'

    html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Airbnb Market Comparison</title>
<style>
* {{ box-sizing: border-box; margin: 0; padding: 0; }}
body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #1a1a2e;
    background: #f5f6fa;
    line-height: 1.6;
}}
.container {{ max-width: 1100px; margin: 0 auto; padding: 20px; }}
header {{
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    color: white;
    padding: 50px 20px;
    text-align: center;
}}
header h1 {{ font-size: 2.2em; font-weight: 700; margin-bottom: 10px; }}
header p {{ font-size: 1.1em; opacity: 0.85; max-width: 750px; margin: 0 auto; }}
header .meta {{ margin-top: 18px; font-size: 0.85em; opacity: 0.6; }}
.section {{
    background: white;
    border-radius: 12px;
    padding: 35px;
    margin: 25px 0;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
}}
.section h2 {{
    font-size: 1.5em;
    font-weight: 700;
    margin-bottom: 8px;
    color: #0f3460;
    border-bottom: 3px solid #2196F3;
    padding-bottom: 10px;
    display: inline-block;
}}
.section .objective {{
    color: #666;
    font-size: 0.95em;
