def build_report(stats, charts):
    kpi_rows = generate_kpi_table(stats)

    # Find extremes for takeaways
    max_price_city = max(CITIES_ORDER, key=lambda c: stats[c]['price_median'] or 0)
    min_price_city = min(CITIES_ORDER, key=lambda c: stats[c]['price_median'] or float('inf'))
    max_pro_city = max(CITIES_ORDER, key=lambda c: stats[c]['pro_host_share'])
    min_pro_city = min(CITIES_ORDER, key=lambda c: stats[c]['pro_host_share'])
    max_entire_city = max(CITIES_ORDER, key=lambda c: stats[c]['room_counts'].get('Entire home/apt', 0) / stats[c]['total_listings'] * 100)
    max_reviews_city = max(CITIES_ORDER, key=lambda c: stats[c]['reviews_pm_mean'] or 0)
    max_avail_city = max(CITIES_ORDER, key=lambda c: stats[c]['avail_mean'] or 0)
    max_listings_city = max(CITIES_ORDER, key=lambda c: stats[c]['total_listings'])

    # Rankings
    price_rank = sorted(CITIES_ORDER, key=lambda c: stats[c]['price_median'] or 0, reverse=True)
    pro_rank = sorted(CITIES_ORDER, key=lambda c: stats[c]['pro_host_share'], reverse=True)

    def stat(s, key, fmt='.1f'):
        val = stats[s].get(key)
        if val is None:
            return 'N/A'
        return f'{val:{fmt}}'

    # Build individual city stats paragraphs
    city_details = ''
    for city in CITIES_ORDER:
        s = stats[city]
        median_p = f"${s['price_median']:.0f}" if s['price_median'] else 'N/A'
        mean_p = f"${s['price_mean']:.0f}" if s['price_mean'] else 'N/A'
        city_details += f'''
        <tr>
            <td style="font-weight:600">{city}</td>
            <td>{s['total_listings']:,}</td>
            <td>{median_p}</td>
            <td>{mean_p}</td>
            <td>{s['room_counts'].get('Entire home/apt', 0) / s['total_listings'] * 100:.1f}%</td>
            <td>{s['pro_host_share']:.1f}%</td>
            <td>{s['reviews_pm_mean']:.2f}</td>
            <td>{s['avail_mean']:.0f}</td>
            <td>{s['min_nights_mean']:.1f}</td>
        </tr>'''

    # Room type price details
    room_price_details = ''
    for city in CITIES_ORDER:
        s = stats[city]
        for rt in ['Entire home/apt', 'Private room', 'Shared room']:
            rps = s['room_price_stats'].get(rt, {})
            if rps:
                room_price_details += f'''
                <tr>
                    <td style="font-weight:600">{city}</td>
                    <td>{rt}</td>
                    <td>{rps['count']:,}</td>
                    <td>${rps['median']:.0f}</td>
                    <td>${rps['mean']:.0f}</td>
                </tr>'''

    # Pro host share for takeaways
    pro_share_strs = []
    for city in CITIES_ORDER:
        s = stats[city]
        pro_share_strs.append(f"<li><strong>{city}:</strong> {s['pro_host_share']:.1f}% of listings from professional hosts, {s['host_listings_mean']:.1f} avg listings/host</li>")

    # Room type breakdown for overview
    room_overview_rows = ''
    for city in CITIES_ORDER:
        s = stats[city]
        room_overview_rows += f'''
        <tr>
            <td style="font-weight:600">{city}</td>
            <td>{s['total_listings']:,}</td>'''
        for rt in ROOM_TYPES:
            c = s['room_counts'].get(rt, 0)
            pct = c / s['total_listings'] * 100 if s['total_listings'] else 0
            room_overview_rows += f'<td>{c:,} ({pct:.1f}%)</td>'
        room_overview_rows += '</tr>'

    html = f'''<!DOCTYPE html>
