        for rt in ROOM_TYPES:
            c = s['room_counts'].get(rt, 0)
            pct = c / s['total_listings'] * 100 if s['total_listings'] else 0
            room_overview_rows += f'<td>{c:,} ({pct:.1f}%)</td>'
        room_overview_rows += '</tr>'

    # Room type price details
    room_price_details = ''
    for city in cities:
        s = stats[city]
        for rt in ['Entire home/apt', 'Private room', 'Shared room']:
            rps = s['room_price_stats'].get(rt, {})
            if rps:
                room_price_details += f'''
                <tr>
                    <td style="font-weight:600">{city}</td>
                    <td>{rt}</td>
                    <td>{rps['count']:,}</td>
                    <td>${rps['median']:.0f}</td>
                    <td>${rps['mean']:.0f}</td>
                </tr>'''

    # Pro host share list for takeaways
    pro_share_strs = ''.join(
