    text-align: center;
    line-height: 30px;
    font-weight: 700;
    font-size: 0.9em;
}}
.rank-badge {{
    display: inline-block;
    padding: 3px 10px;
    border-radius: 12px;
    font-size: 0.8em;
    font-weight: 700;
    color: white;
    margin-right: 4px;
}}
.rank-1 {{ background: #FFD700; color: #333; }}
.rank-2 {{ background: #C0C0C0; color: #333; }}
.rank-3 {{ background: #CD7F32; color: #fff; }}
footer {{
    text-align: center;
    padding: 30px;
    color: #888;
    font-size: 0.85em;
}}
