def fmt_pct(num, denom):
    if denom == 0:
        return '0.0%'
    return f"{num / denom * 100:.1f}%"

def build_report(stats, charts):
    kpi_rows = generate_kpi_table(stats)
    cities = CITIES_ORDER
    n_cities = len(cities)

    # ── Dynamic extremes (no hardcoded city names) ──
    max_price_city = max(cities, key=lambda c: stats[c]['price_median'] or 0)
    min_price_city = min(cities, key=lambda c: stats[c]['price_median'] or float('inf'))
    max_pro_city = max(cities, key=lambda c: stats[c]['pro_host_share'])
    min_pro_city = min(cities, key=lambda c: stats[c]['pro_host_share'])
    max_entire_city = max(cities, key=lambda c: stats[c]['room_counts'].get('Entire home/apt', 0) / stats[c]['total_listings'] * 100)
    second_entire_city = sorted(cities, key=lambda c: stats[c]['room_counts'].get('Entire home/apt', 0) / stats[c]['total_listings'] * 100, reverse=True)[1]
    max_reviews_city = max(cities, key=lambda c: stats[c]['reviews_pm_mean'] or 0)
    max_avail_city = max(cities, key=lambda c: stats[c]['avail_mean'] or 0)
    max_listings_city = max(cities, key=lambda c: stats[c]['total_listings'])
    min_listings_city = min(cities, key=lambda c: stats[c]['total_listings'])
    max_min_nights_city = max(cities, key=lambda c: stats[c]['min_nights_mean'] or 0)
    second_listings_city = sorted(cities, key=lambda c: stats[c]['total_listings'], reverse=True)[1] if n_cities >= 2 else cities[0]
    price_dispersion_city = max(cities, key=lambda c: (stats[c]['price_p75'] or 0) - (stats[c]['price_p25'] or 0))
    tight_price_city = min(cities, key=lambda c: (stats[c]['price_p75'] or 0) - (stats[c]['price_p25'] or 0))
    recent_3m_city = max(cities, key=lambda c: stats[c]['review_recent_3m_pct'])
    mean_price_max_gap_city = max(cities, key=lambda c: (stats[c]['price_mean'] or 0) - (stats[c]['price_median'] or 0))

    # Rankings
    price_rank = sorted(cities, key=lambda c: stats[c]['price_median'] or 0, reverse=True)
    pro_rank = sorted(cities, key=lambda c: stats[c]['pro_host_share'], reverse=True)
    entire_rank = sorted(cities, key=lambda c: stats[c]['room_counts'].get('Entire home/apt', 0) / stats[c]['total_listings'] * 100, reverse=True)

    # Price multiple
    top_price = stats[price_rank[0]]['price_median'] or 1
    bottom_price = stats[price_rank[-1]]['price_median'] or 1
    price_multiple = top_price / bottom_price if bottom_price > 0 else 0

    # Pro host multiple
    top_pro = stats[max_pro_city]['pro_host_share']
    bottom_pro = stats[min_pro_city]['pro_host_share']
    pro_multiple = top_pro / max(0.1, bottom_pro) if bottom_pro > 0 else 0

    # Total listings
    total_all = sum(s['total_listings'] for s in stats.values())
    total_missing_price = sum(s['price_missing'] for s in stats.values())
    missing_pct = total_missing_price / total_all * 100 if total_all else 0

    # Top 2 cities by listings
    listings_sorted = sorted(cities, key=lambda c: stats[c]['total_listings'], reverse=True)
    top2_share = (stats[listings_sorted[0]]['total_listings'] + stats[listings_sorted[1]]['total_listings']) / total_all * 100 if total_all else 0

    # Room type breakdown rows
    room_overview_rows = ''
    for city in cities:
        s = stats[city]
        room_overview_rows += f'''
        <tr>
            <td style="font-weight:600">{city}</td>
            <td>{s['total_listings']:,}</td>'''
        for rt in ROOM_TYPES:
            c = s['room_counts'].get(rt, 0)
            pct = c / s['total_listings'] * 100 if s['total_listings'] else 0
            room_overview_rows += f'<td>{c:,} ({pct:.1f}%)</td>'
        room_overview_rows += '</tr>'

    # Room type price details
    room_price_details = ''
    for city in cities:
        s = stats[city]
        for rt in ['Entire home/apt', 'Private room', 'Shared room']:
            rps = s['room_price_stats'].get(rt, {})
            if rps:
                room_price_details += f'''
                <tr>
                    <td style="font-weight:600">{city}</td>
                    <td>{rt}</td>
                    <td>{rps['count']:,}</td>
                    <td>${rps['median']:.0f}</td>
                    <td>${rps['mean']:.0f}</td>
                </tr>'''

    # Pro host share list for takeaways
    pro_share_strs = ''.join(
        f"<li><strong>{city}:</strong> {stats[city]['pro_host_share']:.1f}% of listings from professional hosts, {stats[city]['host_listings_mean']:.1f} avg listings/host</li>"
        for city in cities
    )

    # Entire home premium by city
    entire_premium_rows = ''
    for city in cities:
        s = stats[city]
        entire_med = (s['room_price_stats'].get('Entire home/apt', {}).get('median') or 0)
        private_med = (s['room_price_stats'].get('Private room', {}).get('median') or 0)
        premium = entire_med - private_med
        premium_ratio = entire_med / private_med if private_med else 0
        entire_premium_rows += f'''
        <tr>
            <td style="font-weight:600">{city}</td>
            <td>${entire_med:.0f}</td>
            <td>${private_med:.0f}</td>
            <td>${premium:.0f}</td>
            <td>{premium_ratio:.1f}x</td>
        </tr>'''

    # Price ranking badges
    price_badges_html = " &gt; ".join(
        f'<span class="rank-badge rank-{i+1}">#{i+1}</span> {c} (${stats[c]["price_median"]:.0f})'
        for i, c in enumerate(price_rank)
    )

    # Find missing price cities
    missing_by_city = sorted(
        [(c, stats[c]['price_missing'] / stats[c]['total_listings'] * 100) for c in cities],
        key=lambda x: -x[1]
    )

    # Dynamic city list for subheading
    city_list_str = ', '.join(cities[:-1]) + ', and ' + cities[-1]

    # Mean availability range
    min_avail_city_key = min(cities, key=lambda c: stats[c]['avail_mean'] or 999)

    # Find cities with private room share > 35%
    high_private_cities = [c for c in cities if stats[c]['room_counts'].get('Private room', 0) / stats[c]['total_listings'] * 100 > 35]

    html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Airbnb Market Comparison</title>
<style>
* {{ box-sizing: border-box; margin: 0; padding: 0; }}
body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #1a1a2e;
    background: #f5f6fa;
    line-height: 1.6;
}}
.container {{ max-width: 1100px; margin: 0 auto; padding: 20px; }}
header {{
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    color: white;
    padding: 50px 20px;
    text-align: center;
}}
header h1 {{ font-size: 2.2em; font-weight: 700; margin-bottom: 10px; }}
header p {{ font-size: 1.1em; opacity: 0.85; max-width: 750px; margin: 0 auto; }}
header .meta {{ margin-top: 18px; font-size: 0.85em; opacity: 0.6; }}
.section {{
    background: white;
    border-radius: 12px;
    padding: 35px;
    margin: 25px 0;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
}}
.section h2 {{
    font-size: 1.5em;
    font-weight: 700;
    margin-bottom: 8px;
    color: #0f3460;
    border-bottom: 3px solid #2196F3;
    padding-bottom: 10px;
    display: inline-block;
}}
.section .objective {{
    color: #666;
    font-size: 0.95em;
    margin-bottom: 25px;
    font-style: italic;
}}
.chart-container {{
    margin: 30px 0;
    text-align: center;
    overflow-x: auto;
}}
.chart-container svg {{
    max-width: 100%;
    height: auto;
}}
table {{
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-size: 0.9em;
}}
th {{
    background: #0f3460;
    color: white;
    padding: 12px 10px;
    text-align: left;
    font-weight: 600;
    white-space: nowrap;
}}
td {{ padding: 10px 10px; border-bottom: 1px solid #eee; }}
tr:hover {{ background: #e3f2fd !important; }}
.kpi-highlight {{
    display: inline-block;
    background: #e3f2fd;
    border-left: 4px solid #2196F3;
    padding: 8px 16px;
    margin: 4px 2px;
    border-radius: 4px;
    font-size: 0.92em;
}}
.takeaway-list {{
    counter-reset: takeaway;
    list-style: none;
    padding: 0;
}}
.takeaway-list li {{
    counter-increment: takeaway;
    margin: 18px 0;
    padding: 16px 20px 16px 60px;
    background: #f8f9fa;
    border-radius: 8px;
    position: relative;
    border-left: 4px solid #2196F3;
}}
.takeaway-list li::before {{
    content: counter(takeaway);
    position: absolute;
    left: 14px;
    top: 14px;
    background: #2196F3;
    color: white;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    text-align: center;
    line-height: 30px;
    font-weight: 700;
    font-size: 0.9em;
}}
.rank-badge {{
    display: inline-block;
    padding: 3px 10px;
    border-radius: 12px;
    font-size: 0.8em;
    font-weight: 700;
    color: white;
    margin-right: 4px;
}}
.rank-1 {{ background: #FFD700; color: #333; }}
.rank-2 {{ background: #C0C0C0; color: #333; }}
.rank-3 {{ background: #CD7F32; color: #fff; }}
footer {{
    text-align: center;
    padding: 30px;
    color: #888;
    font-size: 0.85em;
}}
.fact-box {{
    background: #fff3e0;
    border-left: 4px solid #FF9800;
    padding: 14px 18px;
    margin: 16px 0;
    border-radius: 6px;
    font-size: 0.95em;
}}
.note {{ font-size: 0.85em; color: #888; margin-top: 8px; }}
</style>
</head>
<body>

<header>
    <h1>Global Airbnb Market Comparison</h1>
    <p>Pricing, Supply &amp; Guest Demand Across {n_cities} Major Cities</p>
    <p style="margin-top:14px; max-width:700px; font-size:0.95em;">A comprehensive cross-city analysis of Airbnb listings across {city_list_str} — examining pricing dynamics, room-type distribution, host concentration, and guest engagement patterns.</p>
    <div class="meta">Data source: Inside Airbnb &bull; Scrape date: March 29, 2026 &bull; {total_all:,} listings analyzed</div>
</header>

<div class="container">

<!-- ── SECTION 1: Market Overview ────────────────────────────────────────── -->
<div class="section" id="market-overview">
    <h2>1. Global Market Overview</h2>
    <p class="objective">Summarize the total number of listings per city, overall price distribution, and room-type breakdown to establish the scale and composition of each market.</p>

    <p>The dataset encompasses <strong>{total_all:,} Airbnb listings</strong> across {n_cities} major global cities. Listing counts range widely — from <strong>{min_listings_city}</strong> at {stats[min_listings_city]['total_listings']:,} to <strong>{max_listings_city}</strong> at {stats[max_listings_city]['total_listings']:,} — reflecting differences in market maturity, regulatory environments, and city size.</p>

    <div class="chart-container">
        {charts['listing_counts']}
    </div>

    <p>The room-type mix reveals clear levels of market commercialization. <strong>{max_entire_city}</strong> leads with entire-home rentals at <strong>{stats[max_entire_city]['room_counts'].get('Entire home/apt', 0) / stats[max_entire_city]['total_listings'] * 100:.1f}%</strong> of its supply, while cities with lower entire-home shares reflect more traditional homeshare dynamics. Shared rooms remain a negligible share across all markets (typically &lt;3%).</p>

    <h3 style="margin-top:25px;">Room Type Breakdown by City</h3>
    <table>
        <thead><tr>
            <th>City</th><th>Total Listings</th>
            <th>Entire Home/Apt</th><th>Private Room</th><th>Shared Room</th><th>Hotel Room</th>
        </tr></thead>
        <tbody>{room_overview_rows}</tbody>
    </table>

    <div class="chart-container">
        {charts['room_type_dist']}
    </div>

    <div class="fact-box">
        <strong>Key observation:</strong> The two largest markets by volume — <strong>{listings_sorted[0]}</strong> ({stats[listings_sorted[0]]['total_listings']:,}) and <strong>{listings_sorted[1]}</strong> ({stats[listings_sorted[1]]['total_listings']:,}) — together account for <strong>{top2_share:.1f}%</strong> of all listings in the dataset. However, their pricing profiles diverge significantly, as detailed in the next section.
    </div>
</div>

<!-- ── SECTION 2: Pricing Analysis ───────────────────────────────────────── -->
<div class="section" id="pricing-analysis">
    <h2>2. Pricing Dynamics Across Cities</h2>
    <p class="objective">Compare median and average nightly prices by city and room type, identify the most and least expensive markets, and highlight price dispersion within each city.</p>

    <h3>Price Rankings (Median Nightly Rate, USD)</h3>
    <p style="margin:10px 0;">
        {price_badges_html}
    </p>

    <div class="chart-container">
        {charts['price_median']}
    </div>

    <p><strong>{price_rank[0]}</strong> commands the highest median price at <strong>${stats[price_rank[0]]['price_median']:.0f}/night</strong>, positioning it as the premium market. At the opposite end, <strong>{price_rank[-1]}</strong> is the most affordable at <strong>${stats[price_rank[-1]]['price_median']:.0f}/night</strong> — a <strong>{price_multiple:.1f}x</strong> difference between the top and bottom markets. Mean prices are consistently higher than medians across all cities (indicating right-skewed distributions with luxury-tier outliers), with the gap most pronounced in <strong>{mean_price_max_gap_city}</strong> and <strong>{price_rank[1]}</strong>.</p>

    <div class="chart-container">
        {charts['price_boxplot']}
    </div>

    <p>The boxplot above (outliers above $1,000 excluded for readability) reveals significant price dispersion within each market. <strong>{price_dispersion_city}</strong> shows the widest interquartile range, while <strong>{tight_price_city}</strong> has the most compressed pricing.</p>

    <h3 style="margin-top:25px;">Entire-Home Premium by City</h3>
    <table>
        <thead><tr>
            <th>City</th><th>Median Entire Home</th><th>Median Private Room</th><th>Premium ($)</th><th>Ratio</th>
        </tr></thead>
        <tbody>{entire_premium_rows}</tbody>
    </table>

    <h3 style="margin-top:25px;">Median Price by Room Type Across Cities</h3>
    <div class="chart-container">
        {charts['price_by_room_type']}
    </div>

    <h3 style="margin-top:25px;">Room-Type Price Matrix (USD)</h3>
    <table>
        <thead><tr>
            <th>City</th><th>Room Type</th><th>Count</th><th>Median Price</th><th>Mean Price</th>
        </tr></thead>
        <tbody>{room_price_details}</tbody>
    </table>

    <div class="fact-box">
        <strong>Investor insight:</strong> The entire-home premium — the gap between entire-home and private-room median prices — varies dramatically by city. This gap signals the marginal return on offering a full unit versus a shared space, and is widest in cities with strong tourist demand and constrained hotel supply.
    </div>

    <p class="note">Note: {total_missing_price:,} listings ({missing_pct:.1f}%) had missing price values and were excluded from price calculations. Cities with the highest missing-price rates: {', '.join(f'{c} ({p:.1f}%)' for c, p in missing_by_city[:3])}.</p>
</div>

<!-- ── SECTION 3: Supply Structure ───────────────────────────────────────── -->
<div class="section" id="supply-structure">
    <h2>3. Supply Structure &amp; Host Concentration</h2>
    <p class="objective">Analyze the distribution of room types per city, examine host listing counts to assess professional vs. individual host prevalence, and identify cities with the highest host concentration.</p>

    <div class="chart-container">
        {charts['pro_hosts']}
    </div>

    <p>Professional hosts — defined as hosts with <strong>5 or more listings</strong> — represent a strategically critical dimension of market structure. High professional-host concentration indicates an investable, operator-driven market; low concentration signals a more fragmented, individual-host landscape with different competitive dynamics and regulatory risk profiles.</p>

    <h3 style="margin-top:25px;">Professional Host Concentration by City</h3>
    <table>
        <thead><tr>
            <th>City</th><th>Total Listings</th><th>Pro Host Listings (5+)</th><th>Pro Host Share</th><th>Avg Listings/Host</th>
            <th>Entire Home Share</th>
        </tr></thead>
        <tbody>
            {"".join(f"<tr><td style='font-weight:600'>{c}</td><td>{stats[c]['total_listings']:,}</td><td>{stats[c]['pro_host_count']:,}</td><td>{stats[c]['pro_host_share']:.1f}%</td><td>{stats[c]['host_listings_mean']:.1f}</td><td>{stats[c]['room_counts'].get('Entire home/apt', 0) / stats[c]['total_listings'] * 100:.1f}%</td></tr>" for c in cities)}
        </tbody>
    </table>

    <ul style="margin:20px 0;">
        {pro_share_strs}
    </ul>

    <p><strong>{max_pro_city}</strong> has the highest professional-host concentration at <strong>{stats[max_pro_city]['pro_host_share']:.1f}%</strong>, nearly <strong>{pro_multiple:.1f}x</strong> the level of <strong>{min_pro_city}</strong> ({stats[min_pro_city]['pro_host_share']:.1f}%). Markets with high professionalization tend to be more scalable from an operator perspective but also face greater regulatory scrutiny — an important consideration for market-entry strategies.</p>

    <div class="fact-box">
        <strong>Regulatory watch:</strong> Cities with high entire-home shares coupled with high professional-host concentration (like <strong>{max_pro_city}</strong> and <strong>{pro_rank[1]}</strong>) are most exposed to short-term rental regulations targeting commercial operators. Investors should monitor local policy environments closely in these markets.
    </div>
</div>

<!-- ── SECTION 4: Guest Demand ───────────────────────────────────────────── -->
<div class="section" id="guest-demand">
    <h2>4. Guest Demand &amp; Review Activity</h2>
    <p class="objective">Use review metrics as demand proxies to compare guest engagement across cities and room types, and identify recency patterns.</p>

    <div class="chart-container">
        {charts['reviews_per_month']}
    </div>

    <p>Reviews per month serves as the strongest available proxy for booking frequency. <strong>{max_reviews_city}</strong> leads with a mean of <strong>{stats[max_reviews_city]['reviews_pm_mean']:.2f} reviews/month</strong>, suggesting strong and consistent demand. The gap between mean and median review rates across all cities indicates a subset of high-performing listings drive outsized review volumes — likely professionally managed units with optimized pricing and availability.</p>

    <div class="chart-container">
        {charts['review_recency']}
    </div>

    <p>Review recency patterns confirm that the majority of listings with review activity have been reviewed within the past 12 months. <strong>{recent_3m_city}</strong> shows the highest share of recently-reviewed listings ({stats[recent_3m_city]['review_recent_3m_pct']:.1f}% within 3 months), indicating an active and current booking base.</p>

    <h3 style="margin-top:25px;">Demand Indicators Summary</h3>
    <table>
        <thead><tr>
            <th>City</th><th>Avg Reviews/Mo</th><th>Median Reviews/Mo</th>
            <th>Avg Total Reviews</th><th>Avg Reviews (LTM)</th>
            <th>3-Mo Review Recency</th><th>12-Mo Review Recency</th>
        </tr></thead>
        <tbody>
            {"".join(f"<tr><td style='font-weight:600'>{c}</td><td>{stats[c]['reviews_pm_mean']:.2f}</td><td>{stats[c]['reviews_pm_median']:.2f}</td><td>{stats[c]['reviews_total_mean']:.0f}</td><td>{stats[c]['reviews_ltm_mean']:.1f}</td><td>{stats[c]['review_recent_3m_pct']:.1f}%</td><td>{stats[c]['review_recent_12m'] / stats[c]['total_listings'] * 100:.1f}%</td></tr>" for c in cities)}
        </tbody>
    </table>
</div>

<!-- ── SECTION 5: Availability & Booking Constraints ──────────────────────── -->
<div class="section" id="availability-minimumnights">
    <h2>5. Availability &amp; Booking Constraints</h2>
    <p class="objective">Examine availability and minimum-night distributions across cities to understand listing accessibility and potential regulatory impacts.</p>

    <div class="chart-container">
        {charts['availability']}
    </div>

    <p>Mean availability across cities ranges from <strong>{stats[min_avail_city_key]['avail_mean']:.0f} days/year</strong> ({min_avail_city_key}) to <strong>{stats[max_avail_city]['avail_mean']:.0f} days/year</strong> ({max_avail_city}). High availability (&gt;250 days) typically signals two possible dynamics: (1) a market with lower occupancy and weaker demand, or (2) a market with a large share of dedicated short-term rental inventory (as opposed to occasionally-rented primary residences). <strong>{max_avail_city}</strong>'s high mean availability ({stats[max_avail_city]['avail_mean']:.0f} days) aligns with its high professional-host share, suggesting the latter.</p>

    <div class="chart-container">
        {charts['minimum_nights']}
    </div>

    <p>Minimum-night requirements are a critical signal of regulatory influence. Cities with high mean minimum nights often reflect local short-term rental caps (e.g., 30-night or 90-night annual limits), which operators comply with by setting long minimum stays. <strong>{max_min_nights_city}</strong> stands out with a mean minimum of <strong>{stats[max_min_nights_city]['min_nights_mean']:.1f} nights</strong> — notably higher than other cities — likely driven by a combination of regulatory frameworks and long-stay tourist patterns.</p>

    <div class="chart-container">
        {charts['price_vs_avail']}
    </div>

    <p>The price-availability scatterplot above reveals market archetypes. The upper-right quadrant (high price, high availability) represents commercially-oriented, premium markets. The lower-left (low price, low availability) signals more residential, occasional-hosting markets. The bubble sizes reflect total listings, giving a sense of market scale alongside positioning.</p>
</div>

<!-- ── SECTION 6: Key Takeaways ──────────────────────────────────────────── -->
<div class="section" id="key-takeaways">
    <h2>6. Key Takeaways &amp; Strategic Implications</h2>
    <p class="objective">Synthesize findings into actionable insights for investors, hosts, and policymakers.</p>

    <ol class="takeaway-list">
        <li>
            <strong>Premium pricing power is concentrated in Western European gateway cities.</strong>
            {price_rank[0]} (${stats[price_rank[0]]['price_median']:.0f}), {price_rank[1]} (${stats[price_rank[1]]['price_median']:.0f}), and {price_rank[2]} (${stats[price_rank[2]]['price_median']:.0f}) top the median-price rankings. These markets command a significant premium over other destinations — {price_rank[0]} is <strong>{price_multiple:.1f}x</strong> more expensive per night than {price_rank[-1]}. For investors seeking revenue-per-unit maximization, these remain the top-tier markets — but with correspondingly high barriers to entry.
        </li>
        <li>
            <strong>Professional host concentration defines market character and regulatory exposure.</strong>
            {max_pro_city} ({stats[max_pro_city]['pro_host_share']:.1f}%) and {pro_rank[1]} ({stats[pro_rank[1]]['pro_host_share']:.1f}%) have the highest professional-host shares, making them attractive for scaled operators but also the most exposed to anti-commercialization regulations. At the other extreme, {min_pro_city} ({stats[min_pro_city]['pro_host_share']:.1f}%) remains dominated by individual hosts — lower operational complexity but harder to scale.
        </li>
        <li>
            <strong>Entire-home dominance signals commercialization; private-room strength signals authentic homeshare.</strong>
            {entire_rank[0]} ({stats[entire_rank[0]]['room_counts'].get('Entire home/apt', 0) / stats[entire_rank[0]]['total_listings'] * 100:.1f}% entire-home) and {entire_rank[1]} ({stats[entire_rank[1]]['room_counts'].get('Entire home/apt', 0) / stats[entire_rank[1]]['total_listings'] * 100:.1f}%) are the most commercialized markets by room-type mix.{' Cities with balanced private-room shares (&gt;35%), such as ' + ', '.join(high_private_cities) + ', represent a different value proposition: lower ADR but potentially more regulatory resilience and local community alignment.' if high_private_cities else ''}
        </li>
        <li>
            <strong>Guest demand, proxied by review activity, is strongest in {max_reviews_city}.</strong>
            At {stats[max_reviews_city]['reviews_pm_mean']:.2f} average reviews per month, {max_reviews_city} leads all cities in guest engagement. Review recency data shows {stats[max_reviews_city]['review_recent_3m_pct']:.1f}% of its listings were reviewed within the last 3 months. For investors seeking cash-flow velocity (frequent bookings, consistent turnover), high-review-velocity markets merit priority consideration.
        </li>
        <li>
            <strong>High availability coupled with high prices signals dedicated STR inventory, not weak demand.</strong>
            {max_avail_city} demonstrates the archetype: {stats[max_avail_city]['avail_mean']:.0f} mean available days/year alongside a median price of ${stats[max_avail_city]['price_median']:.0f}. This combination — high availability AND strong pricing — is the hallmark of a professionalized market with purpose-built short-term rental supply, rather than a market with low occupancy. Investors should read availability in context with price and professional-host share, not in isolation.
        </li>
        <li>
            <strong>Minimum-night requirements are early-warning signals for regulatory constraints.</strong>
            Cities with elevated minimum-night means (notably {max_min_nights_city} at {stats[max_min_nights_city]['min_nights_mean']:.1f} nights) warrant careful regulatory due diligence. Long minimum stays often reflect local ordinances capping annual rental nights — operators compensate by requiring longer individual stays. Before entering any market, cross-reference minimum-night data with local STR ordinances.
        </li>
        <li>
            <strong>The dataset has data-quality gaps that affect certain analyses.</strong>
            {total_missing_price:,} listings ({missing_pct:.1f}%) lack pricing data, with missing rates varying by city. {missing_by_city[0][0] if missing_by_city else 'Some cities'} and {missing_by_city[1][0] if len(missing_by_city) > 1 else 'others'} have notably higher missing-price rates. Additionally, some cities have significant zero-review listing inventories, which may represent inactive or newly-listed properties. These gaps should be factored into market-sizing and revenue projections.
        </li>
    </ol>

    <h3 style="margin-top:30px;">KPI Summary Dashboard</h3>
    <div style="overflow-x:auto;">
        {format_kpi_rows(kpi_rows)}
    </div>
</div>

</div>

<footer>
    <p>Global Airbnb Market Comparison Report &bull; Generated May 7, 2026 &bull; Data source: Inside Airbnb (CC BY 4.0)</p>
    <p>All figures derived from the provided dataset spanning {n_cities} cities. No external data or assumptions were used.</p>
</footer>

</body>
</html>'''
